from pathlib import Path
import re,json,html
root=Path(__file__).resolve().parent.parent/'dist'
products={}
paths=list((root/'journeys').glob('*/index.html'))+[root/'silk-road-luxury-trains/index.html',root/'yangtze-river-cruises/index.html']+list((root/'experiences').glob('*/index.html'))+list((root/'signature-experiences').glob('*/index.html'))+list((root/'wildlife').glob('*/index.html'))
for p in paths:
 s=p.read_text(); slug=p.parent.name;title=html.unescape(re.search(r'<title>(.*?) \| SUKHA</title>',s).group(1));products[slug]=title
 block=f'<section class="wrap section narrow product-payment"><p class="eyebrow">ALREADY HAVE A CONFIRMED QUOTE?</p><h2>Pay for your journey.</h2><p>Pay the full amount agreed with your travel designer using WeChat or Alipay. Have your confirmed order and payment instructions ready.</p><a class="button" href="/payment/?product={slug}">Pay in Full <span>↗</span></a></section>'
 if 'class="wrap section narrow product-payment"' not in s:s=s.replace('</main>',block+'</main>')
 p.write_text(s)
base=(root/'index.html').read_text().split('<body')[0].replace('<title>China, Beyond the Expected | SUKHA</title>','<title>Full Payment | SUKHA</title>')
base=re.sub(r'<link rel="canonical"[^>]*>','',base);base=re.sub(r'<meta property="og:[^>]*>','',base)
body='''<body><header><a href="/" class="wordmark">SUKHA</a><span class="quiet">FULL PAYMENT · 微信 / 支付宝</span></header><main class="wrap section narrow"><p class="eyebrow">YOUR JOURNEY · FULL PAYMENT</p><h1 style="font-size:48px">One step closer<br>to your journey.</h1><h2 id="product-title" style="font-size:28px">Choose a product first</h2><div id="missing" hidden><p>Please open this page from your journey’s payment button.</p><a href="/private-china-tours/" class="button">Explore Journeys</a></div><div id="payment-flow" hidden><div class="notice"><strong>Before paying</strong><p style="margin:8px 0 0">Use the full amount and currency in your confirmed quotation. This page does not calculate prices or exchange rates. If your payment app shows a different currency or recipient, stop and contact your travel designer.</p></div><p style="margin-top:25px">Recipient / 收款人: <strong>贺文峰 · HE WENFENG</strong></p><p class="quiet">This is the individual recipient designated by SUKHA. Your contracting company and payment authorization should match the instructions supplied with your confirmed order.</p><label class="check"><input type="checkbox" id="confirmed"><span>I have a confirmed order and written instructions authorizing payment to 贺文峰. I have checked the full amount and currency.</span></label><fieldset id="methods" disabled><legend style="font-size:24px">Choose your payment method</legend><div class="payment-options"><button type="button" data-method="wechat" aria-pressed="false">WeChat Pay<br><small>微信支付</small></button><button type="button" data-method="alipay" aria-pressed="false">Alipay<br><small>支付宝</small></button></div></fieldset><section id="qr-panel" hidden aria-live="polite"><h2 id="method-title" style="font-size:28px;margin-top:35px"></h2><p>Scan with the corresponding app. Check the recipient before confirming your payment.</p><img id="payment-qr" alt="" style="width:100%;max-width:320px;height:auto;object-fit:contain;margin:20px auto;background:white;padding:15px"><a id="download-qr" class="text-link" download>Download QR Code ↓</a><p class="quiet" style="margin-top:15px">On a phone, save the image and use your payment app’s image scanning option if available, or scan from another screen.</p><button type="button" class="button" id="after-payment">I’ve paid — next steps →</button><div id="next-instructions" hidden class="notice" style="margin-top:24px"><strong>Payment is not yet verified.</strong><p style="margin:10px 0">Send your order reference, transaction reference, amount, currency and payment time to the travel designer who provided your quotation, using your existing contact channel. They will check receipt and confirm your booking.</p><p style="margin:0">This page does not send a notification, upload a receipt or check your wallet. Opening these instructions does not mark an order as paid. Do not pay again while awaiting verification.</p></div></section></div></main><footer><span>© 2026 SUKHA · 行界</span><a href="/">Back to home</a></footer><style>.payment-options{display:grid;grid-template-columns:1fr 1fr;gap:15px}.payment-options button{padding:23px;background:#f3f0e8;border:1px solid #cbd0c7;color:#263d37;font-size:16px}.payment-options button[aria-pressed=true]{border:2px solid #263d37;background:#e5ebe3}.payment-options button:disabled{opacity:.45;cursor:not-allowed}fieldset:disabled .payment-options{opacity:.45}#qr-panel{text-align:center}#next-instructions{text-align:left}#download-qr{display:block;width:fit-content;margin:0 auto 24px}header{justify-content:space-between}@media(max-width:600px){main h1{font-size:38px!important}.payment-options button{padding:18px 10px}header .quiet{font-size:9px}}</style><script src="/payment/payment.js"></script></body></html>'''
(root/'payment').mkdir(exist_ok=True);(root/'payment/index.html').write_text(base+body)
js='const products='+json.dumps(products,ensure_ascii=False)+''';
const $=s=>document.querySelector(s);const selected=products[new URLSearchParams(location.search).get('product')];
if(selected){$('#product-title').textContent=selected;$('#payment-flow').hidden=false;}else{$('#missing').hidden=false;}
$('#confirmed').addEventListener('change',()=>{$('#methods').disabled=!$('#confirmed').checked;if(!$('#confirmed').checked){$('#qr-panel').hidden=true;document.querySelectorAll('[data-method]').forEach(b=>b.setAttribute('aria-pressed','false'));}});
document.querySelectorAll('[data-method]').forEach(b=>b.addEventListener('click',()=>{if(!$('#confirmed').checked)return;const method=b.dataset.method;const title=method==='wechat'?'WeChat Pay · 微信支付':'Alipay · 支付宝';$('#method-title').textContent=title;$('#payment-qr').src='/assets/payments/'+method+'.jpg';$('#payment-qr').alt=title+' QR code, recipient 贺文峰';$('#download-qr').href=$('#payment-qr').src;$('#download-qr').download='SUKHA-'+method+'.jpg';$('#qr-panel').hidden=false;$('#next-instructions').hidden=true;document.querySelectorAll('[data-method]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
$('#after-payment').addEventListener('click',()=>{$('#next-instructions').hidden=false;$('#next-instructions').scrollIntoView({behavior:'smooth',block:'nearest'});});
'''
(root/'payment/payment.js').write_text(js)
print('Added full-payment links to',len(products),'product pages; QR chooser ready.')
